import{_ as a,o as t,c as n,ah as s}from"./chunks/framework.ChH6X6u6.js";const m=JSON.parse('{"title":"Bien démarrer","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/prise-en-main.md","filePath":"src/guide/prise-en-main.md"}'),i={name:"guide/prise-en-main.md"};function r(o,e,u,l,c,d){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="bien-demarrer" tabindex="-1">Bien démarrer <a class="header-anchor" href="#bien-demarrer" aria-label="Permalink to &quot;Bien démarrer&quot;">​</a></h1><p>Cette page est commune à tous les rôles : connexion, profil, sécurité, notifications et langue fonctionnent de la même façon, que vous soyez administrateur, enseignant, parent ou élève. Les guides propres à chaque rôle (menu de gauche) ne répètent pas ces informations.</p><h2 id="se-connecter" tabindex="-1">Se connecter <a class="header-anchor" href="#se-connecter" aria-label="Permalink to &quot;Se connecter&quot;">​</a></h2><p>Ouvrez l&#39;adresse de votre établissement dans un navigateur et saisissez votre e-mail et votre mot de passe sur l&#39;écran de connexion. Si votre établissement l&#39;a activé, vous pouvez aussi vous connecter avec un compte Google ou Apple.</p><p>Si l&#39;authentification à deux facteurs est activée sur votre compte, un code supplémentaire vous sera demandé après le mot de passe (voir « Authentification à deux facteurs » plus bas).</p><p>Une fois connecté, vous arrivez sur votre tableau de bord — son contenu dépend de votre rôle.</p><h2 id="parametres-du-compte" tabindex="-1">Paramètres du compte <a class="header-anchor" href="#parametres-du-compte" aria-label="Permalink to &quot;Paramètres du compte&quot;">​</a></h2><p>Le menu <strong>Paramètres</strong> (accessible depuis votre avatar, en haut de l&#39;écran) regroupe tout ce qui concerne votre compte personnel, quel que soit votre rôle :</p><ul><li><strong>Profil</strong> — modifier votre nom, votre adresse e-mail et votre photo de profil. Si vous changez d&#39;adresse e-mail, un message « Votre adresse e-mail n&#39;est pas vérifiée » apparaît jusqu&#39;à ce que vous cliquiez sur le lien reçu par e-mail.</li><li><strong>Sécurité</strong> — changer votre mot de passe, activer l&#39;authentification à deux facteurs, gérer vos clés d&#39;accès (connexion sans mot de passe) et consulter vos sessions actives.</li><li><strong>Apparence</strong> — choisir entre thème clair, sombre ou automatique.</li><li><strong>Langue</strong> — choisir la langue de l&#39;application (français ou anglais). Ce choix change immédiatement tous les libellés, y compris ceux de ce guide si vous y accédez depuis l&#39;app.</li><li><strong>Notifications</strong> — activer les notifications push sur cet appareil.</li></ul><h3 id="authentification-a-deux-facteurs-2fa" tabindex="-1">Authentification à deux facteurs (2FA) <a class="header-anchor" href="#authentification-a-deux-facteurs-2fa" aria-label="Permalink to &quot;Authentification à deux facteurs (2FA)&quot;">​</a></h3><p>Dans <strong>Paramètres → Sécurité → Authentification à deux facteurs</strong>, cliquez sur <strong>Activer la 2FA</strong>. Un code secret vous sera ensuite demandé à chaque connexion ; il se récupère depuis une application d&#39;authentification (TOTP) installée sur votre téléphone, après avoir scanné le code affiché à l&#39;écran. Pour désactiver la 2FA, retournez sur cette même page et cliquez sur <strong>Désactiver la 2FA</strong>.</p><h3 id="sessions-actives" tabindex="-1">Sessions actives <a class="header-anchor" href="#sessions-actives" aria-label="Permalink to &quot;Sessions actives&quot;">​</a></h3><p><strong>Paramètres → Sécurité → Sessions actives</strong> liste tous les appareils actuellement connectés à votre compte, avec l&#39;appareil, l&#39;adresse IP et la dernière activité. L&#39;appareil que vous utilisez en ce moment est marqué <strong>Appareil actuel</strong>. Vous pouvez :</p><ul><li><strong>Déconnecter</strong> un appareil précis (il devra se reconnecter),</li><li><strong>Déconnecter les autres appareils</strong> pour fermer toutes les sessions sauf celle en cours — utile si vous pensez qu&#39;un appareil ne devrait plus avoir accès à votre compte.</li></ul><h3 id="notifications-push" tabindex="-1">Notifications push <a class="header-anchor" href="#notifications-push" aria-label="Permalink to &quot;Notifications push&quot;">​</a></h3><p><strong>Paramètres → Notifications</strong> vous permet d&#39;activer les notifications push sur l&#39;appareil que vous utilisez. Une fois activées, vous êtes notifié dès qu&#39;une action nécessite votre attention (par exemple une demande de transfert inter-site à valider). Le bouton <strong>Activer</strong>/ <strong>Désactiver</strong> bascule cet état ; s&#39;il indique que les notifications ne sont pas prises en charge, c&#39;est que votre navigateur ou votre appareil ne le permet pas.</p><h2 id="la-cloche-de-notifications" tabindex="-1">La cloche de notifications <a class="header-anchor" href="#la-cloche-de-notifications" aria-label="Permalink to &quot;La cloche de notifications&quot;">​</a></h2><p>En haut de l&#39;écran, la cloche affiche un badge quand vous avez des notifications non lues (par exemple une candidature à traiter, ou une demande à valider). Cliquez sur une notification pour l&#39;ouvrir et la marquer comme lue, ou utilisez <strong>Tout marquer comme lu</strong> pour vider la liste d&#39;un coup.</p><h2 id="valider-une-demande-directement-depuis-une-notification" tabindex="-1">Valider une demande directement depuis une notification <a class="header-anchor" href="#valider-une-demande-directement-depuis-une-notification" aria-label="Permalink to &quot;Valider une demande directement depuis une notification&quot;">​</a></h2><p>Certaines notifications ne servent pas seulement à prévenir : elles ouvrent un écran de <strong>validation rapide</strong>, volontairement réduit à l&#39;essentiel, où vous décidez sans naviguer dans le reste de l&#39;app. C&#39;est prévu pour être utilisé depuis un téléphone.</p><p>Trois demandes fonctionnent ainsi :</p><table tabindex="0"><thead><tr><th>Demande</th><th>Qui la valide</th></tr></thead><tbody><tr><td>Transfert d&#39;un élève vers un autre site</td><td>Administration ou secrétariat</td></tr><tr><td>Transfert d&#39;un membre du personnel</td><td>Administration</td></tr><tr><td>Dépense à approuver</td><td>Administration</td></tr></tbody></table><p>L&#39;écran affiche le détail de la demande et deux actions : <strong>Approuver</strong>, qui statue immédiatement, ou <strong>Rejeter</strong>, qui demande d&#39;abord un motif — motif ensuite visible par la personne qui avait déposé la demande.</p><p>Vous pouvez toujours traiter ces demandes de la façon classique, depuis la file correspondante dans le menu. La validation rapide est un raccourci, pas un circuit séparé : une demande déjà traitée depuis une notification apparaît comme traitée dans la file, et inversement.</p><h2 id="pourquoi-certains-menus-n-apparaissent-pas" tabindex="-1">Pourquoi certains menus n&#39;apparaissent pas <a class="header-anchor" href="#pourquoi-certains-menus-n-apparaissent-pas" aria-label="Permalink to &quot;Pourquoi certains menus n&#39;apparaissent pas&quot;">​</a></h2><p>ERA se vend par pôles : un établissement n&#39;active que ceux dont il a besoin. Si un menu attendu n&#39;est pas là, ce n&#39;est pas nécessairement un problème de droits — le pôle concerné n&#39;est peut-être simplement pas inclus dans la licence de l&#39;établissement.</p><p>Deux causes possibles, à distinguer avant de signaler un incident :</p><ul><li><strong>Votre rôle</strong> ne donne pas accès à cette fonction. Un enseignant ne voit pas la caisse, un caissier ne saisit pas de notes.</li><li><strong>Le pôle n&#39;est pas licencié</strong> pour l&#39;établissement. Dans ce cas, personne ne voit la fonction, quel que soit son rôle, et ouvrir l&#39;adresse directement affiche un message indiquant que la fonction n&#39;est pas incluse.</li></ul><p>Votre administrateur peut confirmer lequel des deux cas s&#39;applique.</p><h2 id="changer-de-langue" tabindex="-1">Changer de langue <a class="header-anchor" href="#changer-de-langue" aria-label="Permalink to &quot;Changer de langue&quot;">​</a></h2><p>Le sélecteur de langue (menu <strong>Paramètres → Langue</strong>, ou l&#39;icône de langue dans l&#39;en-tête selon votre rôle) bascule immédiatement toute l&#39;interface entre français et anglais — aucune reconnexion nécessaire.</p><h2 id="conditions-d-utilisation-et-donnees-personnelles" tabindex="-1">Conditions d&#39;utilisation et données personnelles <a class="header-anchor" href="#conditions-d-utilisation-et-donnees-personnelles" aria-label="Permalink to &quot;Conditions d&#39;utilisation et données personnelles&quot;">​</a></h2><p>Deux pages accessibles à tous, y compris sans être connecté, depuis les liens en bas de la page d&#39;accueil :</p><ul><li><strong>CGU / CGV</strong> — les conditions générales d&#39;utilisation et de vente : ce que couvre la licence de votre établissement, la maintenance, et les formules d&#39;hébergement.</li><li><strong>Politique de confidentialité</strong> — quelles données ERA traite sur les élèves, les familles et le personnel, pendant combien de temps elles sont conservées, et qui y a accès.</li></ul><p>Ces deux pages suivent la langue de l&#39;application : elles s&#39;affichent en français ou en anglais selon le réglage de <strong>Paramètres → Langue</strong>.</p>',35)])])}const v=a(i,[["render",r]]);export{m as __pageData,v as default};
